    private static var cache: [Framework: NSImage] = [:]

    /// テンプレート画像（色は表示側で付ける）として返す
    @MainActor
    static func image(for framework: Framework) -> NSImage? {
        if let cached = cache[framework] { return cached }
        guard let d = paths[framework] else { return nil }
        let svg = #"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d=""# + d + #""/></svg>"#
        guard let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.isTemplate = true
        cache[framework] = image
        return image
    }
}
